 async function refresh(){if(!db)return;const [p,c,o]=await Promise.all([db.from('posts').select('*').eq('status','published').order('created_at',{ascending:false}).limit(100),db.from('contents').select('*').eq('published',true).order('created_at',{ascending:false}).limit(100),db.from('opportunities').select('*').eq('status','published').order('created_at',{ascending:false}).limit(100)]);if(p.data)setPosts(p.data as Post[]);if(c.data)setContents(c.data as Content[]);if(!o.error){setOpportunities(o.data as Opportunity[]||[]);setOpportunitiesReady(true)}}
 useEffect(()=>{if(!db)return;db.auth.getSession().then(({data})=>setSession(data.session));const {data:{subscription}}=db.auth.onAuthStateChange((_e,s)=>setSession(s));void refresh();return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{let active=true;async function check(){setAdmin(false);setPending([]);setUsers(null);if(!db||!session)return;const r=await db.from('profiles').select('role').eq('id',session.user.id).maybeSingle();if(!active)return;const isAdmin=r.data?.role==='admin';setAdmin(isAdmin);if(isAdmin){const [n,q]=await Promise.all([db.from('profiles').select('id',{count:'exact',head:true}),db.from('posts').select('*').eq('status','pending').order('created_at',{ascending:true}).limit(100)]);if(active){setUsers(n.count);setPending(q.data as Post[]||[])}}}void check();return()=>{active=false}},[session?.user.id]);
 useEffect(()=>{let active=true;setPrefsLoaded(false);setInterests([]);setSports([]);setGoal('');if(!db||!session)return;void db.from('member_preferences').select('interests,sports,goal,birth_date,gender').eq('user_id',session.user.id).maybeSingle().then(({data,error})=>{if(!active)return;if(error){setMessage('As preferências ainda não estão disponíveis. É necessário executar a migração SQL.');return}setInterests(data?.interests||[]);setSports(data?.sports||[]);setGoal(data?.goal||'');setBirthDate(data?.birth_date||'');setGender(data?.gender||'');setPrefsLoaded(true)});return()=>{active=false}},[session?.user.id]);
 useEffect(()=>{if(!db||!session){setEarned([]);return}let active=true;void Promise.all([db.from('member_preferences').select('interests,sports,goal').eq('user_id',session.user.id).maybeSingle(),db.from('posts').select('id',{count:'exact',head:true}).eq('author_id',session.user.id).eq('status','published')]).then(([prefs,posts])=>{if(active)setEarned([...(prefs.data&&(prefs.data.interests?.length||prefs.data.sports?.length||prefs.data.goal)?['perfil']:[]),...(posts.count&&posts.count>0?['voz']:[])])});return()=>{active=false}},[session?.user.id,prefsSaving,posts.length]);
 async function savePrefs(){if(!db||!session)return;setPrefsSaving(true);const r=await db.from('member_preferences').upsert({user_id:session.user.id,interests,sports,goal,birth_date:birthDate||null,gender:gender||null},{onConflict:'user_id'});setPrefsSaving(false);setMessage(r.error?'Não foi possível guardar: '+r.error.message:'Preferências guardadas no teu F.');}
