 const track=(type:'page_view'|'click'|'story_view',label:string)=>{if(!db||admin)return;try{if(localStorage.getItem('invictas-analytics-consent')!=='yes')return}catch{return}let visitor:null|string=null;try{if(localStorage.getItem('invictas-analytics-consent')==='yes'){visitor=localStorage.getItem('invictas-analytics-visitor');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('invictas-analytics-visitor',visitor)}}}catch{}void db.rpc('track_site_event',{p_type:type,p_label:label,p_visitor:visitor,p_source:sourceFromReferrer()}).then(()=>{})};
