 const setConsent=async(choice:'yes'|'no')=>{if(choice==='no'){let previous:string|null=null;try{previous=localStorage.getItem('invictas-analytics-visitor')}catch{}try{localStorage.setItem('invictas-analytics-consent','no')}catch{}setAnalyticsConsent('no');if(previous&&db){const result=await db.rpc('erase_visitor_events',{p_visitor:previous});if(result.error){setMessage('A recolha de estatísticas foi desativada. Não foi possível confirmar a eliminação do histórico; volta a tentar ou contacta o responsável pela privacidade.');return}}try{localStorage.removeItem('invictas-analytics-visitor')}catch{}return}try{localStorage.setItem('invictas-analytics-consent','yes');if(!localStorage.getItem('invictas-analytics-visitor'))localStorage.setItem('invictas-analytics-visitor',crypto.randomUUID())}catch{}setAnalyticsConsent('yes')};
 const go=(t:string)=>{track('page_view',t);setStoryId(null);setOpenArticle(null);setArticleId(null);if(t==='Para Mim'){setProfileSection('para-mim');t='Perfil'}if(t==='O meu F'){setProfileSection('preferencias');t='Perfil'}if(t==='Percurso F'){setProfileSection('inicio');t='Perfil'}setTab(primaryTab(t));setMessage('');window.scrollTo({top:0,behavior:'smooth'})};
